// The store copy is the REAL package; its deps resolve from HERE, not
// from the symlink that reached it: 'peer' sits beside it in the store
// (exports conditions + a '*' subpath pattern), 'hoistdep' is hoisted at
// the workspace-root node_modules far above this package's own dir.
import { flavor, greetings } from "peer";
import { hello } from "peer/greet/en";
import stamp from "hoistdep";

export function describe(n) {
  return `${hello()} ${greetings.hello()} ${flavor()} ${stamp(n)}`;
}
